package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;

/** What is due on a claim, read from the rates its person's grade has. */
@Component
public class Dues {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final ClaimRepository claims;

    public Dues(RateRepository rates, SheetRepository sheets, ClaimRepository claims) {
        this.rates = rates;
        this.sheets = sheets;
        this.claims = claims;
    }

    /**
     * How a claim's live figures round: by the sheet's policy date against the claim's date, or for a
     * correction the date of the claim it corrects (its own when that claim is not found).
     */
    private RoundingMode rounding(Claim claim, Sheet sheet) {
        LocalDate date = claim.getDate();
        if (claim.getCorrects() != null) {
            date = claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
                    .map(Claim::getDate).orElse(date);
        }
        return sheet == null ? RoundingMode.HALF_EVEN : sheet.roundingOn(date);
    }

    /**
     * The due figure a claim shows: the one fixed when it was settled, else the one its person's last
     * statement bound it to, else its amount at the rate the grade has in force on the claim's date;
     * null (n/a) when there is none.
     */
    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : live(claim, grade);
    }

    /**
     * The due a claim shows: its figure (see {@link #figure}) with the late charge on top while it is
     * overdue; a settled claim's figure already holds the charge it was settled with. Null (n/a) when
     * it has no figure.
     */
    public BigDecimal due(Claim claim, String grade) {
        return withLate(claim, figure(claim, grade));
    }

    /**
     * The due a claim is settled at: the figure a statement bound it to, else its live figure, with
     * the late charge it has on the sheet's today on top; null when it has no figure.
     */
    public BigDecimal settling(Claim claim, String grade) {
        return withLate(claim, claim.isStated() ? claim.getStatedDue() : live(claim, grade));
    }

    /**
     * A figure with the claim's late charge on top: the sheet's late percent of the figure for every
     * full 30 days an OPEN claim is past its due-by (its date plus the sheet's terms) on the sheet's
     * today, rounded by the claim's date against the policy date. The charge is never bound: it always follows the sheet's today.
     * A correction has no late charge.
     */
    private BigDecimal withLate(Claim claim, BigDecimal figure) {
        if (figure == null || claim.isCorrection() || claim.getStatus() != ClaimStatus.OPEN || claim.getSettledDue() != null) {
            return figure;
        }
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        if (sheet == null || sheet.getLatePct().signum() == 0) {
            return figure;
        }
        LocalDate dueBy = claim.getDate().plusDays(sheet.getTerms());
        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / 30;
        if (periods <= 0) {
            return figure;
        }
        BigDecimal late = figure.multiply(sheet.getLatePct()).multiply(BigDecimal.valueOf(periods))
                .movePointLeft(2).setScale(2, rounding(claim, sheet));
        return figure.add(late);
    }

    /**
     * A claim's amount at the rate the grade has in force on the claim's date, raised to the sheet's
     * floor when below it (a correction has no floor), rounded by the claim's date against the policy
     * date; null when it has no rate.
     */
    public BigDecimal live(Claim claim, String grade) {
        Sheet sheet = sheets.findById(claim.getSheetId()).orElse(null);
        BigDecimal floor = claim.isCorrection() || sheet == null ? null : sheet.getFloor();
        RoundingMode rounding = rounding(claim, sheet);
        return rates.findInForce(claim.getSheetId(), grade, claim.getDate())
                .map(rate -> due(claim.getAmount(), rate, rounding))
                .map(due -> floor != null && due.compareTo(floor) < 0 ? floor : due)
                .orElse(null);
    }

    /** What is due on an amount at a rate: the amount times the percent over 100, rounded as given. */
    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /**
     * What the screen is told about a claim; the amount with two decimals, and the due fixed when it
     * was settled (null when not fixed, so its due is worked out from the current rate), and who
     * opened it (null until opened), and whether it is bound by its person's last statement, with the
     * figure it was bound to (null when unbound, or when it was n/a), and the number of the claim it
     * corrects (null unless it is a correction).
     */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects) {

        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects());
        }
    }

    /**
     * A claim's values as entered on the form: the amount is required, with up to two decimals, and
     * below 0.00 only on a correction, which names the number of the claim it corrects; no date means
     * the sheet's today (or, on an edit, the claim's own); the note may be empty.
     */
    public record ClaimForm(
            @NotNull @Pattern(regexp = "-?\\d{1,12}(\\.\\d{1,2})?") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Pattern(regexp = "[1-9]\\d{0,8}|\\S.{0,200}-[1-9]\\d{0,8}") String corrects) {
    }

    /** The claims selected to be opened together. */
    public record BulkOpenForm(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    /** What a bulk open did: the claims opened, as they are now, and how many were refused. */
    public record BulkOpenView(List<ClaimView> opened, int refused) {
    }

    private final ClaimService service;
    private final BulkOpenService bulkOpen;

    public ClaimController(ClaimService service, BulkOpenService bulkOpen) {
        this.service = service;
        this.bulkOpen = bulkOpen;
    }

    /** The sheet's claims, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(ClaimView::of).toList();
    }

    /** Add a claim for a person. */
    @PostMapping("/people/{personId}/claims")
    public ClaimView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long personId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ClaimForm form) {
        return ClaimView.of(service.add(sheetId, SignedIn.name(user), personId, new BigDecimal(form.amount()), form.date(), form.note(), form.corrects()));
    }

    /** Change a claim's amount, date and note. */
    @PutMapping("/claims/{claimId}")
    public ClaimView edit(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ClaimForm form) {
        return ClaimView.of(service.edit(sheetId, SignedIn.name(user), claimId, new BigDecimal(form.amount()), form.date(), form.note(), form.corrects()));
    }

    /** Open a DRAFT claim. */
    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.move(sheetId, SignedIn.name(user), claimId, ClaimStatus.OPEN));
    }

    /** Open the selected claims together, in list order; those that cannot be opened are refused. */
    @PostMapping("/claims/open")
    public BulkOpenView openAll(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid BulkOpenForm form) {
        BulkOpenService.Result result = bulkOpen.open(sheetId, SignedIn.name(user), form.claimIds());
        return new BulkOpenView(result.opened().stream().map(ClaimView::of).toList(), result.refused());
    }

    /** Settle an OPEN claim; refused for the user who opened it. */
    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.move(sheetId, SignedIn.name(user), claimId, ClaimStatus.SETTLED));
    }

    /** Void a DRAFT or OPEN claim. */
    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long claimId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user) {
        return ClaimView.of(service.move(sheetId, SignedIn.name(user), claimId, ClaimStatus.VOID));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * A person's statements: taking one records their due-total on the sheet's today, binds each of
 * their counting claims to the due figure it shows then, and leaves the rest unbound.
 */
@Service
public class StatementService {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** The person as stated, with all of their claims, newest first. */
    public record Stated(Person person, List<Claim> claims) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;

    public StatementService(PersonRepository people, ClaimRepository claims, ClaimService claimService,
            RateRepository rates, SheetService sheets, Rollups rollups, Audit audit) {
        this.rollups = rollups;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Take a statement for a person on the sheet. */
    @Transactional
    public Stated take(String sheetId, String user, long personId) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Rollups.Rollup before = rollups.take(sheetId);
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean figured = false;
        int counted = 0;
        for (Claim claim : theirs) {
            // As in the live totals: an OPEN claim of a person on hold is left out.
            if (!person.countsLive(claim.getStatus())) {
                claim.unbind();
                continue;
            }
            // The statement binds the figure; the late charge stays live, but counts in its total.
            BigDecimal figure = claimService.figure(claim, person.gradeOn(claim.getDate()));
            figured |= figure != null;
            claim.bind(figure);
            counted++;
            BigDecimal due = claimService.due(claim, person.gradeOn(claim.getDate()));
            if (due != null) {
                total = total.add(due);
            }
        }
        // As on the screen: n/a when the grade in force today has no rate, unless a claim has a figure.
        if (rates.findInForce(sheetId, person.gradeOn(today), today).isEmpty() && !figured) {
            total = null;
        }
        person.stated(total, today);
        Person saved = people.saveAndFlush(person);
        List<Claim> bound = claims.saveAllAndFlush(theirs);
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted);
        rollups.audit(sheetId, user, before);
        return new Stated(saved, bound);
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: what each person has claimed and their due-total,
 * and the sheet's claimed-total and due-total. A change takes them before it writes and has them
 * audited after its own records, so every figure it moves is recorded.
 */
@Service
public class Rollups {

    /** Shown in place of a due-total when the grade has no rate. */
    private static final String NO_RATE = "n/a";

    /** A person's figures: what they have claimed and their due-total (null when n/a). */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {

        boolean sameAs(Figures other) {
            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal);
        }
    }

    /** The sheet's figures: each person's by id, in the order they were added, and the sheet's totals. */
    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Dues dues;
    private final Audit audit;

    public Rollups(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            Dues dues, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.dues = dues;
        this.audit = audit;
    }

    /** The sheet's figures as they stand now in the current transaction. */
    public Rollup take(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (claim.getStatus().counts()) {
                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = zero();
        BigDecimal dueTotal = zero();
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> counting = byPerson.getOrDefault(person.getId(), List.of()).stream()
                    .filter(claim -> person.countsLive(claim.getStatus()))
                    .toList();
            BigDecimal claimed = zero();
            BigDecimal due = zero();
            boolean figured = false;
            for (Claim claim : counting) {
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    figured = true;
                }
            }
            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
            // figure (a fixed one, or one at the grade in force on its own date).
            boolean rated = today != null && rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
            if (!rated && !figured) {
                due = null;
            }
            figures.put(person.getId(), new Figures(person.getName(), claimed, due));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) {
                dueTotal = dueTotal.add(due);
            }
        }
        return new Rollup(figures, claimedTotal, dueTotal);
    }

    /**
     * Record, once the change commits, one ROLLUP line per person whose figures moved since
     * {@code before} (a person new since then counts as moved), then a TOTALS line when the sheet's
     * totals moved.
     */
    public void audit(String sheetId, String user, Rollup before) {
        Rollup after = take(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal()));
            }
        });
        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user
                    + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString());
        }
    }

    /** Whether two figures are the same amount, or both n/a. */
    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }

    private static String shown(BigDecimal due) {
        return due != null ? due.toPlainString() : NO_RATE;
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles user names have on a sheet: listed, set and looked up. */
@Service
public class RoleService {

    private final RoleRepository roles;
    private final SheetService sheets;
    private final Audit audit;

    public RoleService(RoleRepository roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<Role> list(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role a user name has on the sheet: the one set for it, else clerk. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
    }

    /** Set the role of a user name on the sheet, replacing any it had. */
    @Transactional
    public Role set(String sheetId, String user, String userName, String role) {
        sheets.lock(sheetId);
        Role saved = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new Role(sheetId, userName, role));
        saved.setRole(role);
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
                + " user=" + saved.getUserName() + " role=" + saved.getRole());
        return saved;
    }
}

